/**
 * format currency $
 * @param
 * hidelt: Do not display <0.01
 * noComma: Do not display comma
 * */
export const formatCurrency = (value: string | number | undefined, decimal: number, hidelt?: boolean, noComma?: boolean) => {
  try {
    if (value === undefined || value === '--') return '$--'
    const num = formatNumberWithDown(value, decimal, true).toString()

    if (d(num).equals(0)) return '$0'
    const isNegative = num.startsWith('-')

    let formattedNum = noComma ? num : addComma(num).toString()
    if (formattedNum.includes('e')) {
      formattedNum = noComma ? num : addCommaWithNoMantissa(num).toString()
    }

    if (!hidelt && Number(num) < Math.pow(10, -decimal)) {
      if (isNegative) {
        return `-$${formattedNum.slice(1)}`
      }
      return `<$${Math.pow(10, -decimal).toFixed(decimal)}`
    }

    return isNegative ? `-$${formattedNum.slice(1)}` : `$${formattedNum}`
  } catch (error) {
    console.log('🚀 ~ formatCurrency ~ error:', error)
    return '$--'
  }
}

export const formatCurrencyUSD = (value: string | number | undefined, decimal: number, noComma?: boolean) => {
  try {
    if (value === undefined || value === '--') return '$--'
    const num = formatNumber(value, decimal, true).toString()
    if (d(num).equals(0)) return '$0'
    const isNegative = num.startsWith('-')
    const formattedNum = noComma ? num : addComma(num).toString()
    return isNegative ? `$0` : `$${formattedNum}`
  } catch (error) {
    console.log('🚀 ~ formatCurrencyUSD ~ error:', error)
    return '$--'
  }
}

export const formatPercentage = (
  value: string | number | undefined,
  decimal: number = 2,
  hidelt: boolean = false,
  notDisplayZero: boolean = false // true 为0时则展示为<0.01
) => {
  if (value === undefined) return '--'
  if (d(value).equals(0)) {
    if (notDisplayZero) {
      return `< ${Math.pow(10, -decimal)}%`
    }
    return '0%'
  }

  if (!hidelt) {
    if (Number(value) >= 0 && Number(value) <= Math.pow(10, -decimal)) {
      return `<${Math.pow(10, -decimal).toFixed(decimal)}%`
    }
    if (Number(value) < 0 && Number(value) * -1 <= Math.pow(10, -decimal)) {
      return ` < -${Math.pow(10, -decimal).toFixed(decimal)}%`
    }
  }
  return `${fixDown(value, decimal)}%`
}

export const formatPercentageGt0And100 = (value: string | number | undefined, decimal: number = 2) => {
  if (typeof value === 'undefined' || value === 'undefined' || (value !== 0 && !value)) return '--'

  if (d(value).abs().gt(100)) {
    return '> 100%'
  }

  if (Number(value) >= 0 && Number(value) <= Math.pow(10, -decimal)) {
    return `<${Math.pow(10, -decimal)}%`
  }
  if (Number(value) < 0 && Number(value) * -1 <= Math.pow(10, -decimal)) {
    return ` < -${Math.pow(10, -decimal)}%`
  }

  const num = fixDown(value, decimal)
  if (Number(num) > 0) {
    return `+${num}%`
  }
  return `${num}%`
}

/**
 *
 * @param value 需处理的数值
 * @param noComma 不展示千位符
 *
 * 规则：
 *  1. 整数>=9位时，可不展示小数
 *  2. 9>整数>=4位时，可最多展示2位小数
 *  3. 4>整数>=1位有效整数时（有效整数只不为0数字），可最多展示4位小数
 *  整数为0时，当小数中
 *  4. 小数位可展示除0外6位有效数字，例如0.041427588666038278展示为0.0414275
 *  5. 第6位依然为0则在第9位小数后+1位小数
 *  6. 第7位依然为0则在第9位小数后+2位小数
 *  7. 第8位依然为0则在第9位小数后+3位小数
 *  8. 第9位依然为0则在第9位小数后+4位小数
 *  ...
 *  最多展示到18位小数 (5,6,7,8暂不实现)
 *
 */
export const formatNumber = (
  value: string | number | undefined,
  decimal?: number,
  noComma?: boolean,
  rounding: Decimal.Rounding = Decimal.ROUND_HALF_DOWN,
  returnZero: boolean = false //位数超过decimal时 返回0 例如formatNumber(0.005,2,false,Decimal.ROUND_HALF_DOWN,true)==>0
) => {
  if (value === '∞') return '∞'
  if (value !== '0' && !value) {
    return '0'
  }
  value = convertScientificToDecimal(value.toString(), decimal)

  if (d(value).equals(0)) return '0'

  if (decimal !== undefined) {
    const result = fixNumber(value, decimal, rounding)
    if (!d(result).equals(0)) {
      return noComma ? result : addComma(result)
    } else {
      if (returnZero) return result
    }
  }

  const str = d(value).toString()
  const arr = str.split('.')
  const integerPart = arr[0]
  const decimalPart = arr[1]
  let result
  if (d(integerPart).gt(0)) {
    if (!decimalPart || d(integerPart.length).gte(9)) {
      result = fixNumber(str, 0, rounding)
    } else if (d(integerPart.length).gte(4)) {
      result = fixNumber(str, 2, rounding)
      // } else if (d(integerPart.length).gte(1)) {
    } else {
      result = fixNumber(str, 4, rounding)
    }
  } else {
    const r = fixNumber(str, 6, rounding)
    const gtZeroIndex = getGtZeroIndex(decimalPart)
    if (gtZeroIndex < 6) {
      result = fixNumber(str, gtZeroIndex + 6, rounding)
      // } else if (gtZeroIndex >= 6 && gtZeroIndex <= 18) {
    } else if (gtZeroIndex >= 6 && gtZeroIndex <= 38) {
      result = fixNumber(str, gtZeroIndex + 4, rounding)
    } else {
      return '0'
    }
  }

  return noComma || d(integerPart).lt(1) ? result : addComma(result)
}
// 同formatNumber但都是向下取整
export const formatNumberWithDown = (value: string | number | undefined, decimal?: number, noComma?: boolean, returnZero: boolean = false) => {
  return formatNumber(value, decimal, noComma, Decimal.ROUND_DOWN, returnZero)
}

export const formatPriceWithDown = (value: string | number | undefined, decimal?: number, noComma?: boolean, returnZero: boolean = false) => {
  let price = formatNumberWithDown(value, decimal, noComma, returnZero)
  if (d(removeComma(price + '')).eq(0) && d(value).gt(0)) {
    price = formatPrice(value, decimal, noComma)
  }
  return price
}

// tick价格展示处理
export const formatTickPrice = (value: string | number | undefined, decimal?: number, noComma?: boolean) => {
  const str = d(value).toString()
  const arr = str.split('.')
  const integerPart = arr[0]
  const decimalPart = arr[1]
  if (integerPart === '0' && decimal) {
    const gtZeroIndex = getGtZeroIndex(decimalPart)
    const gap = decimal - gtZeroIndex
    const dd = gap <= 0 ? Number(gtZeroIndex) : decimal
    if (gap <= 2 && gap > 0) {
      return formatNumber(value, dd + 2, noComma, Decimal.ROUND_DOWN)
    }
    return formatNumber(value, decimal, noComma, Decimal.ROUND_DOWN)
  } else {
    return formatNumber(value, decimal, noComma, Decimal.ROUND_DOWN)
  }
}

// 先使用decimal1 处理 decimal1处理为<0.01以后使用decimal2处理
export const formatNumberWithThreshold = (value: string | number | undefined, decimal1: number, decimal2?: number, noComma?: boolean) => {
  const result = formatNumberWithLtMinPrecision(value, decimal1)
  if (result == `< ${Math.pow(10, -decimal1)}` && decimal2) {
    return String(formatNumberWithLtMinPrecision(value, decimal2))
  }
  return String(result)
}

/**
 *
 * @param value
 * @param decimal
 * @param noComma
 *
 * 规则:
 * 整数大于1，小数位默认展示2位,例如 $10.12、$1,123.12
 * 整数为1位，非0数字，小数默认+3位，例如：$1.123
 * 整数位为0，则小数位像后取4位。例如，$0.9999
 * 整数为0 ，小数位永远展示4个非零有效数字，例如 $0.01234、 $0.0000000001234
 * UI需要修改部分 统计页面token价格 以及swap底部展示
 */
export const formatPrice = (value: string | number | undefined, decimal?: number, noComma?: boolean): string => {
  if (value === '∞') return '∞'
  if (value !== '0' && !value) {
    return '0'
  }
  if (d(value).equals(0)) return '0'

  if (decimal !== undefined) {
    const result = fixDown(value, decimal)
    if (!d(result).equals(0)) {
      return noComma ? String(result) : String(addComma(result))
    }
  }

  const str = d(value).toString()
  const arr = str.split('.')
  const integerPart = arr[0]
  const decimalPart = arr[1]
  let result
  if (d(integerPart).gt(0)) {
    if (d(integerPart).gt(9)) {
      result = fixDown(str, 2)
    } else {
      result = fixDown(str, 3)
    }
  } else {
    const gtZeroIndex = getGtZeroIndex(decimalPart)
    result = fixDown(str, gtZeroIndex + 3)
  }
  return noComma || d(integerPart).lt(1) ? String(result) : String(addComma(result))
}

