/**
 * 处理浮点数并按照指定规则向下取整
 * @param value 要处理的数值（字符串或数字）
 * @returns 处理后的字符串结果
 */
export const formatFloat = (value: string | number): string => {
  // 处理特殊值和无效输入
  if (value === '∞') return '∞'
  if (value !== '0' && !value) return '0'
  if (d(value).equals(0)) return '0'

  const strValue = d(value).toString()
  const [integerPart, decimalPart = ''] = strValue.split('.')
  const integerNum = parseInt(integerPart, 10)

  // 规则1：整数位是0或1时的处理
  if (integerNum === 0 || integerNum === 1) {
    // 先尝试保留4位小数
    let result = fixDown(value, 4)

    // 检查有效小数位数（非零数字的位数）
    const decimalDigits = result.includes('.') ? result.split('.')[1].replace(/0+$/, '').length : 0

    // 如果有效小数位数不足4位，最多取到6位小数
    if (decimalDigits < 4 && decimalPart.length > 4) {
      result = fixDown(value, Math.min(6, decimalPart.length))
    }

    if (result === '0') {
      const gtZeroIndex = getGtZeroIndex(decimalPart)
      result = fixDown(value, gtZeroIndex + 3)
    }

    return result
  }

  // 规则2：其他情况保留2位小数
  return fixDown(value, 2)
}

export const formatBalance = (value?: string | number, decimal?: number, noComma?: boolean) => {
  try {
    if (value === '∞') return '∞'
    if (value !== '0' && !value) {
      return '0'
    }
    if (d(value).equals(0)) return '0'

    if (decimal !== undefined) {
      const result = fixDown(value, decimal)
      if (!d(result).equals(0)) {
        return noComma ? result.toString() : addComma(result).toString()
      }
    }

    const str = d(value).toString()
    const arr = str.split('.')
    const integerPart = arr[0]
    const decimalPart = arr[1]
    let result
    if (d(integerPart).gt(0)) {
      if (!decimalPart || d(integerPart.length).gte(9)) {
        result = fixDown(str, 0)
      } else if (d(integerPart.length).gte(4)) {
        result = fixDown(str, 2)
        // } else if (d(integerPart.length).gte(1)) {
      } else {
        result = fixDown(str, 4)
      }
    } else {
      const r = fixDown(str, 6)
      const gtZeroIndex = getGtZeroIndex(decimalPart)
      if (gtZeroIndex < 6) {
        result = fixDown(str, gtZeroIndex + 6)
      } else {
        if (gtZeroIndex > 30) return '0'
        result = fixDown(str, 9 + (gtZeroIndex - 6))
      }
    }

    return noComma || d(integerPart).lt(1) ? result.toString() : addComma(result).toString()
  } catch (error) {
    return value?.toString() || ''
  }
}

export const formatFeeRate = (value: string | number | undefined, decimal: number = 2) => {
  if (value === '∞') return '∞'
  if (value !== '0' && !value) {
    return '0'
  }
  if (d(value).gte(0.01)) {
    return value
  }
  value = convertScientificToDecimal(value.toString(), decimal)

  if (d(value).equals(0)) return '0'

  const str = d(value).toString()
  const arr = str.split('.')
  const decimalPart = arr[1]
  const gtZeroIndex = getGtZeroIndex(decimalPart)
  return fixNumber(str, gtZeroIndex + decimal, Decimal.ROUND_HALF_DOWN)
}

export const formatNumberWithLtMinPrecision = (value: string | number | undefined, decimal: number = 2, noComma?: boolean) => {
  if (value === '∞') return '∞'
  if (value !== '0' && !value) {
    return '0'
  }
  if (d(value).equals(0)) return '0'

  if (d(value).lt(Math.pow(10, -decimal))) {
    return `< ${Math.pow(10, -decimal)}`
  }
  return formatNumber(value, decimal, noComma)
}

export const formatNumberWithKMB = (value: string | number | undefined, decimal: number = 2, isFixDown = false) => {
  const n = d(value || '0')
  let result
  if (!isFixDown) {
    if (n.gte(Math.pow(10, 9))) {
      result = addComma(fixRounding(n.div(Math.pow(10, 9))?.toString(), decimal)) + 'B'
    } else if (n.gte(Math.pow(10, 6))) {
      result = addComma(fixRounding(n.div(Math.pow(10, 6))?.toString(), decimal)) + 'M'
    } else if (n.gte(d(1000))) {
      result = addComma(fixRounding(n.div(1000)?.toString(), decimal)) + 'K'
    } else {
      result = addComma(fixRounding(Number(value), decimal))
    }
  } else {
    if (n.gte(Math.pow(10, 9))) {
      result = addComma(fixDown(n.div(Math.pow(10, 9))?.toString(), decimal)) + 'B'
    } else if (n.gte(Math.pow(10, 6))) {
      result = addComma(fixDown(n.div(Math.pow(10, 6))?.toString(), decimal)) + 'M'
    } else if (n.gte(d(1000))) {
      result = addComma(fixDown(n.div(1000)?.toString(), decimal)) + 'K'
    } else {
      result = addComma(fixDown(Number(value), decimal))
    }
  }
  return result
}

export const formatCurrencyWithKMB = (value: string | number | undefined, decimal: number = 2) => {
  const n = d(value || '0')
  let result
  if (n.gte(Math.pow(10, 9))) {
    result = formatCurrency(fixRounding(n.div(Math.pow(10, 9))?.toString(), decimal), decimal) + 'B'
  } else {
    result = formatCurrency(value, decimal)
  }
  return result
}

