import HaedalFarmSdk, { farms_mainnet, farms_testnet } from 'haedal-farm-sdk'
import VolatileVaultsSDK, { vaults_mainnet, vaults_testnet } from 'haedal-vault-sdk'
import { create, StateCreator } from 'zustand'

import envConfigs from '@cetus/types/src/config/envConfigs'
import { deepBookMainnetConfig } from '@cetus/types/src/config/mainnet/deepBookMainnet'
import DeepBookUtilsSDK from '@cetusprotocol/deepbook-utils'

interface SDKState {
  volatileVaultsSdk: VolatileVaultsSDK
  setVolatileVaultsSdk: (sdk: VolatileVaultsSDK) => void

  haedalFarmSdk: HaedalFarmSdk
  setHaedalFarmSdk: (sdk: HaedalFarmSdk) => void

  deepBookSDK: DeepBookUtilsSDK
  setDeepBookSDK: (sdk: DeepBookUtilsSDK) => void
}

const store: StateCreator<SDKState> = (set, get) => ({
  volatileVaultsSdk: new VolatileVaultsSDK(envConfigs.env == 'testnet' ? vaults_testnet : vaults_mainnet),
  setVolatileVaultsSdk: (sdk: VolatileVaultsSDK) => {
    set(() => ({
      volatileVaultsSdk: sdk
    }))
  },
  haedalFarmSdk: new HaedalFarmSdk(envConfigs.env == 'testnet' ? farms_testnet : farms_mainnet),
  setHaedalFarmSdk: (sdk: HaedalFarmSdk) => {
    set(() => ({
      haedalFarmSdk: sdk
    }))
  },
  deepBookSDK: new DeepBookUtilsSDK(deepBookMainnetConfig),
  setDeepBookSDK: (sdk: DeepBookUtilsSDK) => {
    set(() => ({
      deepBookSDK: sdk
    }))
  }
})

const usePeripherySDKStore = create(store)
export default usePeripherySDKStore
